                sr=min(rr for _,rr,cc in s_['S']); sc=min(cc for _,rr,cc in s_['S'])
                hb=max(rr for _,rr,cc in s_['S'])-sr+1; wb=max(cc for _,rr,cc in s_['S'])-sc+1
