                    cand={(v,rr+(drr+tr-hr),cc+(dcc+tc-hc)) for v,rr,cc in s_['S']}
                    if cand==ntt: sols.append(('src',s_['key'],'transl',None,'shift=('+str(drr),','+str(dcc)+')'))
